def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([7]), fmt([3, 4, 3]), fmt([1, 2, 3, 4, 5]), fmt([5, 5, 5, 5]),
             fmt([10, 3]), fmt([3, 9, 3]), fmt([12, 1]), fmt([1, 1, 1]), fmt([6, 5, 4, 3, 2, 1])]
    for n in (2, 3, 4, 5, 6, 7, 8):
        for _ in range(3):
            hi = rng.choice([3, 6, 12, 20])
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    n = 50000
    tests.append(fmt([rng.randint(1, 10**8) for _ in range(n)]))
    tests.append(fmt([10**9] * (n - 1) + [1]))
    tests.append(fmt([10**9 - i * 7 for i in range(n)]))
    tests.append(fmt(sorted(rng.randint(1, 10**9) for _ in range(n))))
    tests.append(fmt([rng.choice([1, 10**9, 999999999, 500000000]) for _ in range(n)]))
    return tests

